}

.label.planet {
  color: #dfe7f5;
}

.label.sel {
  color: var(--accent);
  font-weight: 600;
}

.label .dot {
  display: inline-block;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
  margin-right: 5px;
  vertical-align: middle;
  opacity: 0.8;
}

