    count: number;
    orb: Float32Array;
    flags: Uint8Array;
    mag: Float32Array;
    meta: CometMeta;
  };
}

const BASE = 'data/';

async function fetchBin<T>(path: string, ctor: new (b: ArrayBuffer) => T): Promise<T> {
