19	  vec3 orbitToEcliptic(float r, float nu, float w, float i, float om) {
20	    float u = nu + w;
21	    float cu = cos(u), su = sin(u);
22	    float ci = cos(i), si = sin(i);
23	    float co = cos(om), so = sin(om);
24	    return vec3(
25	      r * (co * cu - so * su * ci),
26	      r * (so * cu + co * su * ci),
27	      r * (su * si)
28	    );
29	  }
30	
31	  // M = E - e sin E
32	  float keplerElliptic(float M, float e) {
33	    float m = mod(M, TAU);
34	    float E = m + e * sin(m) * (1.0 + e * cos(m));
35	    for (int k = 0; k < 8; k++) {
36	      float f  = E - e * sin(E) - m;
37	      float fp = 1.0 - e * cos(E);
38	      E -= f / fp;
39	    }
40	    return E;
41	  }
