        const pb = display[b].toLowerCase().indexOf(ql);
        if (pa !== pb) return pa - pb;
      }
      const da = phys[a * PHYS_COLS + P.diameter] || 0;
      const db = phys[b * PHYS_COLS + P.diameter] || 0;
      return db - da;
    })
    .slice(0, 120);
}

