import http from 'node:http';
import { readFile } from 'node:fs/promises';
import { join, extname } from 'node:path';

const ROOT = process.argv[2];
const PORT = +(process.argv[3] || 8712);
const MIME = {
  '.html': 'text/html',
  '.js': 'text/javascript',
  '.css': 'text/css',
  '.json': 'application/json',
  '.f32': 'application/octet-stream',
  '.f64': 'application/octet-stream',
  '.u32': 'application/octet-stream',
  '.u16': 'application/octet-stream',
  '.u8': 'application/octet-stream',
};

http
  .createServer(async (req, res) => {
    let p = decodeURIComponent(req.url.split('?')[0]);
    if (p === '/frame') {
      res.writeHead(200, { 'content-type': 'text/html' });
      res.end('<html><body style="margin:0"><iframe src="/sub/deep/site/" style="width:100vw;height:100vh;border:0"></iframe></body></html>');
      return;
    }
    if (p.startsWith('/sub/deep/site')) p = p.slice('/sub/deep/site'.length) || '/';
    if (p.endsWith('/')) p += 'index.html';
    try {
      const buf = await readFile(join(ROOT, p));
      res.writeHead(200, { 'content-type': MIME[extname(p)] || 'application/octet-stream' });
      res.end(buf);
    } catch {
      res.writeHead(404);
      res.end('nope');
    }
  })
  .listen(PORT, () => console.log('serving', ROOT, 'on', PORT));

